function tmpE2E() {
  const P = '0963183093', today = Utilities.formatDate(new Date(), CONFIG.TZ, 'yyyy-MM-dd'), out = {};
  // 1) 型男課後福利社：放一筆測試學員（今天上課），跑上課當晚的自動 LINE
  const sh = studentSheet_(), perk = String(Math.floor(900000 + Math.random() * 99999));
  sh.appendRow([Utilities.formatDate(new Date(), CONFIG.TZ, 'yyyy-MM-dd HH:mm'), '型男研究所', today, '測試島主', "'" + P, 'TEST', "'" + perk, '未使用', 'TEST-E2E']);
  out.perk = perk; out.push = coursePerkPush();
  // 2) 櫃台一次來訪：岩盤浴 InBody＋精油抓周，一次送出、只發一則 LINE
  const a = deskCreate(ADMIN_KEY, {type: 'inbody', name: '測試島主', phone: P, date: today, service: '岩盤浴（測試）'});
  deskInbody(ADMIN_KEY, a.id, ['70.2', '22.1', '8', '35.0', '40', '1600'], 'before');
  deskInbody(ADMIN_KEY, a.id, ['69.8', '21.7', '8', '35.3', '39', '1598']);
  const b = deskCreate(ADMIN_KEY, {type: 'oil100', name: '測試島主', phone: P, date: today, service: '100 人精油抓周（測試）'});
  deskPut_(deskCase_(b.id), '草稿.json', {title: '測試', words: '這是測試訊息：同一位客人今天做了兩項，應該只收到這一則 LINE。', next: '測試：下一步推薦會在這裡。'});
  out.visit = deskSendVisit(ADMIN_KEY, [{id: a.id, edits: {}}, {id: b.id, edits: {}}]);
  Logger.log(JSON.stringify(out));
}
